// Celebrações do mês e geração de cards comemorativos.
function metasBatidasDoVendedor(slug, contexto = contextoCelebracaoSelecionado()) {
  const d = contexto.d;
  if (!d) return [];
  const vendedorMes = [...(d.intMes || []), ...(d.extMes || [])].find(v => v.slug === slug);
  if (!vendedorMes) return [];
  const cadastro = (contexto.vendedores || []).find(v => String(v.slug || v.id) === String(slug));
  const vendasMes = Number(vendedorMes.vendas || 0);

  if (vendedorMes.tipo === 'interno') {
    const metas = (contexto.cache.metas || []).find(m => String(m.vendedor_id) === String(cadastro?.id));
    const niveis = [
      { value: 'm3', label: 'M3', meta: Number(metas?.meta_m3) },
      { value: 'm2', label: 'M2', meta: Number(metas?.meta_m2) },
      { value: 'm1', label: 'M1', meta: Number(metas?.meta_m1) },
    ].filter(m => Number.isFinite(m.meta) && m.meta > 0).sort((a, b) => a.meta - b.meta);

    return niveis
      .filter(m => vendasMes >= m.meta)
      .reverse()
      .map(m => {
        const proxima = niveis.find(n => n.meta > m.meta);
        return {
          value: m.value,
          label: `${m.label} — Meta Individual do Mês`,
          proxima: proxima ? `${proxima.label} — Meta Individual` : null,
          isFinal: !proxima,
          titulo: `${m.label} CONQUISTADA!`,
        };
      });
  }

  const metaMensal = Number(vendedorMes.meta || 0);
  return metaMensal > 0 && vendasMes >= metaMensal
    ? [{ value: 'individual', label: 'Meta Individual do Mês', proxima: null, isFinal: true, titulo: 'META CONQUISTADA!' }]
    : [];
}

const FRASES_CELEBRACAO_POR_RITMO = {
  acima: [
    'Seu ritmo está tão forte que o Wi-Fi pediu dicas. 🚀',
    'Meta no retrovisor, próximo desafio no radar. Bora!',
    'Seu resultado chegou antes até do sinal. 📶',
    'Você tá voando — até o modem quer pegar carona!',
    'Sua evolução está em alta. O resultado também!',
    'Cliente conectado, meta avançando em alta velocidade!',
  ],
  no: [
    'Ritmo firme, conexão boa e cada venda contando. 📶',
    'Um passo consistente hoje deixa a meta mais perto amanhã.',
    'Tá no ritmo: segue assim que a próxima conquista vem!',
    'Cliente conectado, meta avançando. Boa!',
    'Seu esforço já aparece nos números. Continua!',
    'Seu progresso está fazendo a diferença. Segue firme!',
  ],
  avancando: [
    'Cada venda é uma conexão a mais com a meta.',
    'Todo grande resultado começa com um próximo passo. Bora?',
    'O sinal pode oscilar; sua capacidade continua aí. Vamos nessa!',
    'Respira, ajusta a rota e chama o próximo cliente. Você consegue!',
    'Uma venda de cada vez — o importante é seguir avançando.',
    'A próxima venda pode mudar o ritmo do dia. Vai que é sua!',
  ],
};

function faixaRitmoCelebracao(vendedorMes, slug, contexto = contextoCelebracaoSelecionado()) {
  const cadastro = (contexto.vendedores || []).find(v =>
    String(v.slug || '') === String(slug) || String(v.id) === String(vendedorMes.id)
  );
  let metaPrincipal = Number(vendedorMes.meta || 0);
  if (vendedorMes.tipo === 'interno') {
    const metas = (contexto.cache.metas || []).find(m => String(m.vendedor_id) === String(cadastro?.id));
    metaPrincipal = Math.max(
      Number(metas?.meta_m1) || 0,
      Number(metas?.meta_m2) || 0,
      Number(metas?.meta_m3) || 0
    );
  }
  if (!(metaPrincipal > 0)) return 'avancando';

  const vendas = Number(vendedorMes.vendas || 0);
  const progressoPercentual = (vendas / metaPrincipal) * 100;
  const { diaAtual, diasNoMes } = contexto.mes || calcularPeriodoMes();
  const esperadoPercentual = diasNoMes > 0 ? (diaAtual / diasNoMes) * 100 : 0;
  if (progressoPercentual >= esperadoPercentual + 5) return 'acima';
  if (progressoPercentual >= esperadoPercentual - 5) return 'no';
  return 'avancando';
}

function selecionarFraseCelebracao(slug, ritmo) {
  const frases = FRASES_CELEBRACAO_POR_RITMO[ritmo] || FRASES_CELEBRACAO_POR_RITMO.avancando;
  const chave = `uni-celebracao-frase:${slug}:${ritmo}`;
  let indiceAnterior = -1;
  try {
    indiceAnterior = Number.parseInt(localStorage.getItem(chave), 10);
  } catch (_) { /* armazenamento pode estar indisponível; ainda geramos a arte */ }
  const indice = Number.isInteger(indiceAnterior) && indiceAnterior >= 0
    ? (indiceAnterior + 1) % frases.length
    : Math.floor(Math.random() * frases.length);
  try {
    localStorage.setItem(chave, String(indice));
  } catch (_) { /* a rotação segue em memória enquanto a página estiver aberta */ }
  return frases[indice];
}

// Chamada pelo <select> de vendedor na aba Celebrações — repopula o
// <select> de metas só com as que essa pessoa bateu de verdade.
function atualizarMetasCelebraveis() {
  const vendedorSelect = document.getElementById('cel-vendedor');
  const periodoInput = document.getElementById('cel-periodo');
  const mesAtual = chaveMesPeriodo(_cache.mes || calcularPeriodoMes());
  if (periodoInput) {
    periodoInput.max = mesAtual;
    if (!periodoInput.value) periodoInput.value = mesAtual;
  }
  const slug = vendedorSelect.value;
  const metaSelect = document.getElementById('cel-meta');
  const infoEl = document.getElementById('cel-preview-info');
  const contexto = contextoCelebracaoSelecionado();
  const nomePeriodo = `${contexto.mes?.mesNome || ''} ${contexto.mes?.ano || ''}`.trim();
  if (!slug) {
    metaSelect.innerHTML = '<option value="">Selecione o vendedor primeiro</option>';
    infoEl.textContent = `Período selecionado: ${nomePeriodo}.`;
    return;
  }
  const metas = metasBatidasDoVendedor(slug, contexto);
  if (!metas.length) {
    metaSelect.innerHTML = '<option value="">Nenhuma meta batida no momento</option>';
    infoEl.textContent = `Esse vendedor não atingiu um marco individual em ${nomePeriodo}.`;
    return;
  }
  metaSelect.innerHTML = metas.map(m => `<option value="${m.value}">${m.label}</option>`).join('');
  infoEl.textContent = `${metas.length} marco(s) alcançado(s) em ${nomePeriodo}. A imagem terá formato vertical para Story.`;
}

function obterDadosCelebracaoSelecionada() {
  const slug = document.getElementById('cel-vendedor').value;
  const metaValue = document.getElementById('cel-meta').value;
  const contexto = _celebracaoContextoPeriodo || contextoAnaliticaAtual();
  const d = contexto.d;
  if (!slug || !metaValue) throw new Error('Selecione o vendedor e o marco atingido.');
  if (!d) throw new Error('Ainda não há dados carregados.');
  const metaInfo = metasBatidasDoVendedor(slug, contexto).find(m => m.value === metaValue);
  if (!metaInfo) throw new Error('Esse marco não está mais disponível para esse vendedor. Atualize os dados e tente novamente.');
  const vendedorMes = [...(d.intMes || []), ...(d.extMes || [])].find(v => v.slug === slug);
  if (!vendedorMes) throw new Error('Vendedor não encontrado nos dados mensais.');
  return { slug, metaInfo, vendedorMes, contexto };
}

async function preencherCardCelebracao(slug, metaInfo, vendedorMes, contexto = contextoCelebracaoSelecionado()) {
  const vendedorCadastro = (contexto.vendedores || []).find(v =>
    String(v.slug || '') === String(slug) ||
    String(v.id) === String(vendedorMes.id) ||
    String(v.id) === String(slug)
  );
  const foto = vendedorCadastro?.foto_url || vendedorMes.foto_url || PHOTOS[slug] || PHOTOS[vendedorMes.id] || '';
  const card = document.getElementById('gf-card');
  if (card) {
    card.dataset.achievedTier = ['m3', 'm2', 'm1'].includes(metaInfo.value) ? metaInfo.value : 'meta';
    card.classList.toggle('is-final', Boolean(metaInfo.isFinal));
  }
  const avatar = document.getElementById('gf-avatar');
  const inicial = String(vendedorMes.nome || '?').trim().charAt(0).toUpperCase();
  avatar.replaceChildren();
  if (foto) {
    const img = document.createElement('img');
    img.alt = '';
    img.decoding = 'async';
    img.crossOrigin = 'anonymous';
    avatar.appendChild(img);
    await new Promise(resolve => {
      let concluido = false;
      const terminar = () => {
        if (concluido) return;
        concluido = true;
        clearTimeout(timer);
        resolve();
      };
      const timer = setTimeout(terminar, 8000);
      img.addEventListener('load', terminar, { once: true });
      img.addEventListener('error', terminar, { once: true });
      img.src = foto;
      if (img.complete) terminar();
    });
    if (!img.naturalWidth) avatar.replaceChildren(document.createTextNode(inicial));
  } else {
    avatar.textContent = inicial;
  }

  document.getElementById('gf-nome').textContent = vendedorMes.nome;
  document.getElementById('gf-period').textContent = `${String(contexto.mes?.mesNome || '').toLocaleUpperCase('pt-BR')} ${contexto.mes?.ano || ''}`.trim();
  document.getElementById('gf-meta-label').textContent = metaInfo.label;
  document.getElementById('gf-headline').textContent = metaInfo.titulo || 'META CONQUISTADA!';
  const nextLabel = document.getElementById('gf-next-label');
  const nextText = document.getElementById('gf-proxima');
  const ritmo = faixaRitmoCelebracao(vendedorMes, slug, contexto);
  document.getElementById('gf-motivation').textContent = selecionarFraseCelebracao(slug, ritmo);
  document.getElementById('gf-congrats').textContent = metaInfo.isFinal
    ? (metaInfo.value === 'individual'
      ? `Parabéns, ${vendedorMes.nome}! Você concluiu sua meta do mês. Que conquista!`
      : `Parabéns, ${vendedorMes.nome}! Você chegou ao topo do mês. Que conquista!`)
    : `Parabéns, ${vendedorMes.nome}! Sua dedicação fez essa conquista acontecer.`;
  nextLabel.textContent = metaInfo.isFinal
    ? (metaInfo.value === 'individual' ? 'Meta do mês concluída' : 'Conquista máxima')
    : 'Próxima meta';
  nextText.textContent = metaInfo.isFinal
    ? 'Celebre esse resultado — você fez por merecer!'
    : metaInfo.proxima;
}

function configurarBotoesCelebracao(ativo, mensagem = '') {
  ['cel-gerar-png-btn'].forEach(id => {
    const button = document.getElementById(id);
    if (button) button.disabled = ativo;
  });
  const info = document.getElementById('cel-preview-info');
  if (info && mensagem) info.textContent = mensagem;
}

async function gerarImagemCelebracao() {
  try {
    const { slug, metaInfo, vendedorMes, contexto } = obterDadosCelebracaoSelecionada();
    configurarBotoesCelebracao(true, 'Preparando a imagem…');
    await preencherCardCelebracao(slug, metaInfo, vendedorMes, contexto);
    if (typeof html2canvas === 'undefined') await carregarLibsAdmin();
    if (typeof html2canvas === 'undefined') throw new Error('Não foi possível carregar o gerador de imagens. Tente novamente.');
    if (document.fonts?.ready) await document.fonts.ready;
    const canvas = await html2canvas(document.getElementById('gf-card'), {
      backgroundColor: '#05070d', scale: 2, useCORS: true, allowTaint: false, imageTimeout: 10000,
    });
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    if (!blob) throw new Error('Não foi possível converter a arte em imagem.');
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Conquista_${slug}_${metaInfo.value}_${chaveMesPeriodo(contexto.mes)}.png`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    configurarBotoesCelebracao(false, 'Imagem pronta para compartilhar.');
    showToast('Imagem de comemoração baixada!', 'success');
  } catch (err) {
    console.error('[gerarImagemCelebracao]', err);
    configurarBotoesCelebracao(false, err.message || 'Não foi possível gerar a imagem.');
    showToast(err.message || 'Não foi possível gerar a imagem.', 'error');
  }
}

// ================================================================
// ARTE "DESTAQUE DO MÊS" — peça exclusiva pra quem é o destaque do
// mês (diferente do card de meta individual). Reaproveita o mesmo
// sistema de metas M1/M2/M3 (calcularTiersIndividuais) pra mostrar
// qual foi a melhor meta batida, e a posição real no ranking mensal
// pro selo "Nº_ em vendas" — nada aqui é inventado.
// ================================================================

// (a contagem dos números agora acontece DENTRO do vídeo, desenhada em
// canvas — veja gerarDestaqueDoMes; não precisa mais animar no DOM,
// nem popular partículas de CSS: as partículas do vídeo também são
// desenhadas em canvas, quadro a quadro, dentro da mesma função.)

// Medalhas pré-renderizadas (números 1 a 5) — geradas como imagem
// pronta porque a biblioteca que tira a "foto" do card (html2canvas)
// não desenha bem gradientes de SVG; como PNG, funciona sempre.
const DM_MEDALHAS = {
  1: 'data:image/webp;base64,',
  2: 'data:image/webp;base64,',
  3: 'data:image/webp;base64,',
  4: 'data:image/webp;base64,',
  5: 'data:image/webp;base64,',
};

function aplicarMolduraDestaqueMes(imagem) {
  const largura = 315;
  const altura = 397;
  const escala = 3;
  const canvas = document.createElement('canvas');
  canvas.width = largura * escala;
  canvas.height = altura * escala;
  const contexto = canvas.getContext('2d');
  contexto.scale(escala, escala);
  contexto.beginPath();
  contexto.moveTo(42, 0);
  contexto.lineTo(largura - 42, 0);
  contexto.quadraticCurveTo(largura, 0, largura, 42);
  contexto.lineTo(largura, 337);
  contexto.quadraticCurveTo(largura, 369, 283, 385);
  contexto.quadraticCurveTo(263, 397, 240, 392);
  contexto.lineTo(8, 277);
  contexto.quadraticCurveTo(0, 275, 0, 265);
  contexto.lineTo(0, 42);
  contexto.quadraticCurveTo(0, 0, 42, 0);
  contexto.closePath();
  contexto.clip();

  const proporcao = Math.max(largura / imagem.naturalWidth, altura / imagem.naturalHeight);
  const larguraImagem = imagem.naturalWidth * proporcao;
  const alturaImagem = imagem.naturalHeight * proporcao;
  const x = (largura - larguraImagem) / 2;
  const y = (altura - alturaImagem) * 0.3;
  contexto.drawImage(imagem, x, y, larguraImagem, alturaImagem);
  return canvas.toDataURL('image/png');
}

async function gerarDestaqueDoMes(slug, evt) {
  if (!slug) { showToast('Selecione o vendedor destaque.', 'warning'); return; }
  const contexto = contextoCelebracaoSelecionado();
  const d = contexto.d;
  if (!d) { showToast('Ainda não há dados carregados.', 'warning'); return; }

  const vendedorMes = [...d.intMes, ...d.extMes].find(v => v.slug === slug);
  if (!vendedorMes) { showToast('Vendedor não encontrado.', 'error'); return; }

  const mesNome = (d.mes && d.mes.mesNome) ? (d.mes.mesNome.charAt(0).toUpperCase() + d.mes.mesNome.slice(1)) : CONFIG.mesReferencia;
  const ano = (d.mes && d.mes.ano) || CONFIG.ano;

  const pessoa = PESSOAS[slug] || {};
  const nomeCompleto = pessoa.sobrenome ? `${vendedorMes.nome} ${pessoa.sobrenome}` : vendedorMes.nome;
  const cargo = vendedorMes.tipo === 'interno' ? 'Consultor(a) de Vendas Interno' : 'Consultor(a) de Vendas Externo';

  // ── Preenche o template oculto ──────────────────────────────────
  document.getElementById('dm-mes-pill').textContent = mesNome;
  const filial = window.FILIAL_ATUAL || {};
  const localFilial = String(
    filial.cidade_uf || filial.localizacao || filial.cidade || filial.nome || ''
  ).trim();
  const partesLocal = localFilial.match(/^(.*?)(?:\s*[-–—]\s*([A-Z]{2}))?$/i) || [];
  const nomeCidade = (partesLocal[1] || localFilial)
    .replace(/^(?:regional|filial)(?:\s+(?:de|da|do))?\s+/i, '')
    .trim();
  const ufFilial = filial.uf || filial.sigla_uf || filial.estado_sigla || partesLocal[2] || '';
  const localDestaque = [nomeCidade, ufFilial ? String(ufFilial).toLocaleUpperCase('pt-BR') : '']
    .filter(Boolean)
    .join(' - ');
  const localDestaqueEl = document.getElementById('dm-local');
  localDestaqueEl.textContent = localDestaque.toLocaleUpperCase('pt-BR');
  const contextoTexto = document.createElement('canvas').getContext('2d');
  if (contextoTexto) {
    let tamanhoFonte = 16;
    while (tamanhoFonte > 12) {
      contextoTexto.font = `700 ${tamanhoFonte}px Poppins`;
      const larguraTexto = contextoTexto.measureText(localDestaqueEl.textContent).width
        + localDestaqueEl.textContent.length * 0.6;
      if (larguraTexto <= 532) break;
      tamanhoFonte -= 1;
    }
    localDestaqueEl.style.fontSize = `${tamanhoFonte}px`;
  }
  const fotoDestaque = vendedorMes.foto_url || PHOTOS[slug] || '';
  const fotoDestaqueEl = document.getElementById('dm-photo');
  const fotoDestaqueFallback = document.getElementById('dm-photo-fallback');
  const inicialDestaque = String(vendedorMes.nome || '?').trim().charAt(0).toUpperCase();
  if (fotoDestaque) {
    fotoDestaqueEl.crossOrigin = 'anonymous';
    fotoDestaqueEl.onerror = () => {
      fotoDestaqueEl.style.display = 'none';
      if (fotoDestaqueFallback) {
        fotoDestaqueFallback.textContent = inicialDestaque;
        fotoDestaqueFallback.hidden = false;
      }
    };
    fotoDestaqueEl.style.display = '';
    if (fotoDestaqueFallback) fotoDestaqueFallback.hidden = true;
    fotoDestaqueEl.src = fotoDestaque;
    try {
      if (fotoDestaqueEl.decode) await fotoDestaqueEl.decode();
    } catch (_) {
      fotoDestaqueEl.style.display = 'none';
      if (fotoDestaqueFallback) {
        fotoDestaqueFallback.textContent = inicialDestaque;
        fotoDestaqueFallback.hidden = false;
      }
    }
    if (fotoDestaqueEl.style.display !== 'none') {
      try {
        fotoDestaqueEl.src = aplicarMolduraDestaqueMes(fotoDestaqueEl);
        if (fotoDestaqueEl.decode) await fotoDestaqueEl.decode();
      } catch (err) {
        console.warn('[gerarDestaqueDoMes] Não foi possível aplicar a moldura da foto.', err);
      }
    }
  } else {
    fotoDestaqueEl.removeAttribute('src');
    fotoDestaqueEl.style.display = 'none';
    if (fotoDestaqueFallback) {
      fotoDestaqueFallback.textContent = inicialDestaque;
      fotoDestaqueFallback.hidden = false;
    }
  }
  const nomeEl = document.getElementById('dm-name');
  nomeEl.textContent = nomeCompleto;
  nomeEl.style.fontSize = '34px';
  if (nomeEl.scrollWidth > nomeEl.clientWidth) {
    nomeEl.style.fontSize = `${Math.max(22, 34 * nomeEl.clientWidth / nomeEl.scrollWidth)}px`;
  }
  document.getElementById('dm-role2').textContent = cargo;

  const btn = evt ? evt.target.closest('button') : null;
  const textoOriginalBtn = btn ? btn.textContent : null;
  if (btn) { btn.disabled = true; btn.textContent = 'Gerando imagem...'; }
  try {
    if (typeof html2canvas === 'undefined') {
      carregarLibsAdmin(); showToast('Biblioteca de imagem ainda carregando — aguarde alguns segundos e tente de novo.', 'error');
      if (btn) { btn.disabled = false; btn.textContent = textoOriginalBtn; }
      return;
    }

    if (document.fonts?.ready) await document.fonts.ready;
    const cardEl = document.getElementById('dm-card');
    await Promise.all(Array.from(cardEl.querySelectorAll('img'), img =>
      img.decode ? img.decode().catch(() => {}) : Promise.resolve()
    ));
    // A referência exportada do Canva usa 1080 × 1920 (Story). Renderiza
    // nessa resolução para manter a proporção e evitar uma imagem enorme.
    const canvas = await html2canvas(cardEl, {
      backgroundColor: '#000fe3',
      scale: 1080 / cardEl.offsetWidth,
      useCORS: true,
      allowTaint: false,
      imageTimeout: 10000,
    });
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `DestaqueDoMes_${nomeCompleto.replace(/\s+/g, '_')}_${mesNome}${ano}.png`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast('Imagem de Destaque do Mês gerada com sucesso!', 'success');
    if (btn) { btn.disabled = false; btn.textContent = textoOriginalBtn; }
  } catch (err) {
    console.error('[gerarDestaqueDoMes]', err);
    showToast('Não foi possível gerar a imagem.', 'error');
    if (btn) { btn.disabled = false; btn.textContent = textoOriginalBtn; }
  }
}


// Popula a seção "Metas Configuradas" do ADM com dados reais das
// tabelas metas (individuais) e metas_filial (semanal/mensal).
